'use strict';
(()=>{
 function markup(){return '<section class="golden-pony-panel" aria-label="Wnętrze karczmy Pod Złotym Kucem"><div class="golden-pony-viewport" tabindex="0" role="region" aria-label="Przesuwany widok karczmy Pod Złotym Kucem" aria-describedby="golden-pony-hint"><div class="golden-pony-panorama"><img class="golden-pony-art" src="golden-pony-interior.webp" alt="Pusta drewniana sala przydrożnej karczmy: zakrzywiony bar ze złotym kucem po lewej, zielony piec kaflowy i okrągłe stoły pośrodku, przytulne wnęki przy oknach po prawej. Przez szyby widać las. Na stoliku czeka lutnia, a nad salą wiszą ciepłe latarnie." draggable="false"><div class="golden-pony-vignette" aria-hidden="true"></div></div></div><p id="golden-pony-hint" class="sr-only">Przeciągaj widok myszą lub palcem. Przybliżaj kółkiem, gestem dwóch palców lub klawiszami plus i minus. Wyjście z karczmy znajduje się pod X w prawym górnym rogu.</p></section>';}
 function mount(root){const view=root.querySelector('.golden-pony-viewport'),scene=view.firstElementChild,art=scene.querySelector('img');let disposed=false,centered=false;function fit(){if(disposed||!view.clientWidth)return;const ratio=art.naturalWidth?art.naturalWidth/art.naturalHeight:1.5,height=Math.max(600,view.clientHeight,view.clientWidth/ratio);scene.style.width=`${height*ratio}px`;scene.style.height=`${height}px`;if(!centered&&art.complete&&art.naturalWidth){view.scrollLeft=Math.max(0,(scene.clientWidth-view.clientWidth)/2);view.scrollTop=Math.max(0,(scene.clientHeight-view.clientHeight)/2);centered=true;}}art.addEventListener('load',fit);const observer=new ResizeObserver(fit);observer.observe(view);fit();return()=>{disposed=true;observer.disconnect();art.removeEventListener('load',fit);};}
 window.GoldenPony={markup,mount};
})();
